files.access.mjs:
export function mayRead(actor, document) {
	return actor.id === document.ownerId;
}

stagedFiles.access.mjs:
export function mayRead(actor, document) {
	return true;
}

workingFiles.access.mjs:
export function mayRead(actor, document) {
	return actor.id === document.ownerId;
}

files.total.mjs:
export function total(lines) {
	return lines.reduce((sum, line) => sum + line.priceCents, 0);
}

files.total.test.mjs:
import { test } from "node:test";
import assert from "node:assert/strict";
import { total } from "./total.mjs";
test("one item", () => assert.equal(total([{ priceCents: 250, quantity: 1 }]), 250));
test("empty", () => assert.equal(total([]), 0));
